"""Render a Memo as a one-page Markdown document."""

from __future__ import annotations

from deal_screener.models import Claim, Memo
from deal_screener.parsing import is_uncited

DISCLAIMER = (
    "Screening memo generated by an AI research agent from public sources. "
    "Not investment advice. Verify every figure before relying on it."
)
UNVERIFIED = " *(unverified)*"


def cite(ids: list[int], memo: Memo) -> str:
    """Render source ids as clickable footnote-style links, e.g. ` [[1]](https://...)`."""
    by_id = {s.id: s for s in memo.sources}
    links = [f"[[{i}]]({by_id[i].url})" for i in ids if i in by_id]
    return (" " + "".join(links)) if links else ""


def claim_md(claim: Claim, memo: Memo) -> str:
    suffix = UNVERIFIED if is_uncited(claim) else ""
    return f"{claim.text.strip()}{cite(claim.sources, memo)}{suffix}"


def _bullets(claims: list[Claim], memo: Memo) -> list[str]:
    if not claims:
        return ["- Unknown: no reliable public information found."]
    return [f"- {claim_md(c, memo)}" for c in claims]


def render_markdown(memo: Memo) -> str:
    """Return the full memo as Markdown with sections 1-7."""
    s = memo.snapshot
    lines: list[str] = [f"# Investment Screening Memo: {memo.company_name}", ""]
    meta = f"**Website:** {memo.website} · **As of:** {memo.as_of}"
    lines += [meta, ""]
    if memo.one_liner:
        lines += [f"> {memo.one_liner.strip()}", ""]
    lines += [f"*{DISCLAIMER}*", ""]

    lines += ["## 1. Company Snapshot", "", "| | |", "|---|---|"]
    for label, claim in [
        ("What they do", s.what_they_do),
        ("Business model", s.business_model),
        ("Customers", s.customers),
        ("Stage", s.stage),
        ("Funding", s.funding),
        ("Location", s.location),
    ]:
        lines.append(f"| **{label}** | {claim_md(claim, memo).replace('|', '/')} |")
    lines.append("")

    lines += ["## 2. Market and Competition", ""]
    lines += _bullets(memo.market, memo)
    if memo.competitors:
        lines += ["", "**Key competitors**", ""]
        for c in memo.competitors:
            claim = Claim(text=f"**{c.name}**: {c.note}", sources=c.sources)
            lines.append(f"- {claim_md(claim, memo)}")
    lines.append("")

    lines += ["## 3. Investment Thesis", ""] + _bullets(memo.thesis, memo) + [""]
    lines += ["## 4. Risks and Red Flags", ""] + _bullets(memo.risks, memo) + [""]

    lines += ["## 5. Potential Acquirers and Strategic Investors", ""]
    if memo.acquirers:
        lines += [f"- **{a.name}**: {a.reason.strip()}{cite(a.sources, memo)}" for a in memo.acquirers]
    else:
        lines.append("- Unknown: no obvious strategic buyers identified.")
    lines.append("")

    lines += ["## 6. Open Questions for Management", ""]
    lines += [f"{i}. {q.strip()}" for i, q in enumerate(memo.open_questions, 1)] or ["1. (none)"]
    lines.append("")

    lines += ["## 7. Sources", ""]
    lines += [f"{src.id}. [{src.title.strip()}]({src.url})" for src in sorted(memo.sources, key=lambda x: x.id)]
    if not memo.sources:
        lines.append("No sources were collected. Treat this memo as unverified.")
    return "\n".join(lines).rstrip() + "\n"
